insert into public.course_modules (id, course_id, title, position) values ('5e36cd84-19d4-4405-ab84-73a95f54e3aa', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'VTIARA values and presentation', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('623afaf1-8163-4943-ad32-3e219ea1ae5e', '5e36cd84-19d4-4405-ab84-73a95f54e3aa', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'VTIARA values and standards', 'What ''One Standard'' means across every role and branch.', 25, 'Welcome to VTIARA. Our standard is the same in every room and every role: safe, respectful, consistent care. In this lesson we walk through the VTIARA values and how they show up in everyday decisions.', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('39bdf38c-ecfb-4b1e-a581-c6957d80f50a', '5e36cd84-19d4-4405-ab84-73a95f54e3aa', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Grooming and professional presentation', 'Uniform, grooming, jewellery, nails and personal hygiene expectations.', 20, 'Your presentation tells patients how seriously we take their care. We cover uniform, nails, hair, jewellery and personal hygiene, and why each matters in a clinical setting.', 2) on conflict (id) do nothing;
insert into public.course_modules (id, course_id, title, position) values ('ca414e25-8f85-4ba0-ad70-b6a5e193691c', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Patient communication and skin & hair basics', 2) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('6ecc9d8d-fe8f-47e4-ae05-47954d3821e5', 'ca414e25-8f85-4ba0-ad70-b6a5e193691c', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Patient communication', 'Greeting, listening, empathy, and knowing when to hand over to a clinician.', 30, 'Good communication starts with a warm greeting and active listening. If a patient asks a clinical question, you acknowledge it and refer them to the doctor. You never diagnose or prescribe.', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('984ed515-0fe2-4969-ac5a-d32d2c459418', 'ca414e25-8f85-4ba0-ad70-b6a5e193691c', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Skin and hair basics', 'Plain-language structure of skin and hair, to support — never replace — clinical advice.', 35, 'This lesson gives you a shared vocabulary for skin layers, the hair growth cycle and common concerns, so you can understand your colleagues and support patients within your role.', 2) on conflict (id) do nothing;
insert into public.course_modules (id, course_id, title, position) values ('f1d910b8-5cd5-4807-a725-77724b17b305', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Hygiene and infection control', 3) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('89024a62-12fe-4880-a5fd-46e407bad077', 'f1d910b8-5cd5-4807-a725-77724b17b305', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Hand hygiene: the five moments', 'When and how to clean hands; rub versus wash; common mistakes.', 30, 'Clean hands before touching a patient, before a clean or aseptic task, after body-fluid exposure, after touching a patient and after touching patient surroundings. Rub for 20 to 30 seconds, or wash for 40 to 60 seconds when hands are visibly soiled.', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('4b5c7a59-8a21-4625-a81e-46a0277ab615', 'f1d910b8-5cd5-4807-a725-77724b17b305', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Infection control and biomedical waste', 'Standard precautions, PPE, safe sharps handling and colour-coded waste segregation.', 40, 'Treat every patient with standard precautions. Sharps go in a puncture-proof container without recapping. Segregate waste at the point of generation using the colour-coded system.', 2) on conflict (id) do nothing;
insert into public.course_modules (id, course_id, title, position) values ('af41e1ab-0be4-43f8-afee-1b20af3ad799', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Consent, privacy and emergencies', 4) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('3169cb4d-d571-40d0-a255-8ca1308faeff', 'af41e1ab-0be4-43f8-afee-1b20af3ad799', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Consent, privacy and confidentiality', 'Informed consent, patient photos, data safety and what never to share.', 35, 'Consent must be informed, voluntary and documented. Patient information is shared only with those who need it, in private, and photos are taken only with consent on approved devices.', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, course_id, title, description, duration_min, transcript, position) values ('242617f3-2f34-4ad6-af18-8726578c3f04', 'af41e1ab-0be4-43f8-afee-1b20af3ad799', 'dd52be85-85a5-44e5-a2fb-58d7769dbdae', 'Fire and emergency awareness', 'Raising the alarm, evacuation, and escalating medical emergencies.', 30, 'If a patient collapses or a fire starts, raise the alarm, stay calm and follow the clinic emergency plan. Your role is to escalate quickly and support, not to treat.', 2) on conflict (id) do nothing;
